/bin/bash -lc "python3 - <<'PY'
import os, stat
root='public'
try:
 s=os.lstat(root)
 if not stat.S_ISDIR(s.st_mode) or stat.S_ISLNK(s.st_mode):
  print('ROOT_NOT_DIRECTORY_OR_SYMLINK'); raise SystemExit
except OSError as e:
 print('ROOT_ERROR', type(e).__name__, str(e)); raise SystemExit
try:
 s=os.lstat(os.path.join(root,'cover.txt'))
 print('TARGET', 'regular file' if stat.S_ISREG(s.st_mode) else 'symlink' if stat.S_ISLNK(s.st_mode) else 'other')
except OSError as e:
 print('TARGET_ERROR', type(e).__name__, str(e))
stack=[root]; paths=[]; errors=[]; truncated=False
while stack:
 d=stack.pop()
 try:
  with os.scandir(d) as it: entries=sorted(it,key=lambda x:x.name)
 except OSError as e:
  errors.append((d,type(e).__name__,str(e))); continue
 for ent in entries:
  try:
   if ent.is_symlink(): kind='symlink'
   elif ent.is_dir(follow_symlinks=False): kind='directory'
   elif ent.is_file(follow_symlinks=False): kind='file'
   else: kind='other'
  except OSError as e:
   errors.append((ent.path,type(e).__name__,str(e))); continue
  paths.append((ent.path,kind))
  if len(paths)>50: truncated=True; break
  if kind=='directory': stack.append(ent.path)
 if truncated: break
for p,k in paths[:50]: print('ENTRY',k,repr(p))
for e in errors: print('ERROR',repr(e))
print('INVENTORY', 'truncated' if truncated else 'completed', 'returned',min(len(paths),50))
PY"

